import subprocess, os

def run_bash(cmd):
    # compare with bash behavior to understand expectations
    try:
        r=subprocess.run(["bash","-c",cmd], capture_output=True, text=True, timeout=1)
        return r.stdout, r.stderr, r.returncode
    except Exception as e:
        return "", str(e), 999

def run_nsh(cmd, timeout=1):
    try:
        r=subprocess.run(["./executable","-c",cmd], capture_output=True, text=True, timeout=timeout)
        return r.stdout, r.stderr, r.returncode
    except subprocess.TimeoutExpired as e:
        return (e.stdout.decode() if e.stdout else ""), (e.stderr.decode() if e.stderr else ""), "TIMEOUT"

# Test important differences:
# 1) set -e behavior: after set -e, a failing command should exit shell (or script)
for cmd in ['set -e; false; echo hi', 'set -e; true; echo hi', 'set -e; false || true; echo hi']:
    print("nsh:", run_nsh(cmd))
    print("bash:", run_bash(cmd))
    print("---")

# 2) set -u: accessing undefined var should error and maybe exit?
for cmd in ['set -u; echo $UNDEF; echo hi', 'echo $UNDEF; echo hi']:
    print("nsh:", run_nsh(cmd))
    print("bash:", run_bash(cmd))
    print("---")

# 3) set -n: should not execute? We saw nsh does not execute when set -n
for cmd in ['set -n; echo hi; echo ho', 'set -n; echo hi; set +n; echo ho']:
    print("nsh:", run_nsh(cmd))
    print("bash:", run_bash(cmd))
    print("---")

