        if to_run.trim_start().starts_with("alias") { return self.builtin_alias(&to_run); }
        if to_run.trim_start().starts_with("source ") { return self.builtin_source(&to_run); }
        if to_run.trim_start().starts_with("set ") || to_run.trim() == "set" { return self.builtin_set(&to_run); }
