        if !norc {
            shell.load_nshrc();
        }
        shell.interactive_loop();
    }
}

struct Shell {
    env: HashMap<String, String>,
    aliases: HashMap<String, String>,
    last_status: i32,
    options_e: bool,
    options_u: bool,
    options_n: bool,
    is_login: bool,
}

impl Shell {
    fn new(is_login: bool) -> Self {
        let mut env = HashMap::new();
        for (k,v) in env::vars() {
            env.insert(k,v);
        }
        Shell {
            env,
            aliases: HashMap::new(),
            last_status: 0,
            options_e: false,
            options_u: false,
            options_n: false,
            is_login,
        }
    }
    fn load_nshrc(&mut self) {
        if let Some(home) = self.env.get("HOME").cloned() {
            let path = format!("{}/.nshrc", home);
            if Path::new(&path).exists() {
                if let Ok(content) = fs::read_to_string(&path) {
                    let _ = self.exec_string(&content);
                }
            }
        }
        if let Some(xdg) = self.env.get("XDG_CONFIG_HOME").cloned() {
            let path = format!("{}/nsh/nshrc", xdg);
            if Path::new(&path).exists() {
                if let Ok(content) = fs::read_to_string(&path) {
                    let _ = self.exec_string(&content);
                }
            }
        }
    }
    fn interactive_loop(&mut self) {
        use std::io::BufRead;
        let stdin = io::stdin();
        let mut line = String::new();
        loop {
            print!("$ ");
            io::stdout().flush().unwrap();
            line.clear();
            let n = stdin.lock().read_line(&mut line).unwrap_or(0);
            if n == 0 { break; }
            let trimmed = line.trim_end().to_string();
            if trimmed.is_empty() { continue; }
            self.write_history(&trimmed);
            let code = self.exec_string(&trimmed);
            if self.options_e && code != 0 { exit(code); }
        }
    }
    fn write_history(&self, cmd: &str) {
        let home = match self.env.get("HOME") { Some(h) => h.clone(), None => return };
        let path = format!("{}/.nsh_history", home);
        let cwd = env::current_dir().unwrap_or_else(|_| Path::new(".").to_path_buf());
        let cwd_str = cwd.to_string_lossy().to_string();
        let time = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs();
        let line = format!("{}\t{}\t{}\n", time, cwd_str, cmd);
        let _ = fs::OpenOptions::new().create(true).append(true).open(&path).and_then(|mut f| f.write_all(line.as_bytes()));
    }
    fn exec_string(&mut self, s: &str) -> i32 {
        if self.options_n {
            return 0;
        }
        if s.trim().is_empty() {
            return 0;
        }
        if let Some((msg, code)) = self.check_parse_errors(s) {
            eprintln!("{}", msg);
            self.last_status = code;
            log_error(&msg);
            return code;
        }
        if self.is_panic_break(s) {
            self.panic_unexpected("Break");
            return 101;
        }
        if self.is_panic_continue(s) {
            self.panic_unexpected("Continue");
            return 101;
        }
        if self.is_panic_return(s) {
            self.panic_unexpected("Return");
            return 101;
        }
        if s.contains("*[") {
            self.panic_glob();
            return 101;
        }
        let mut processed = s.to_string();
        if processed.contains("||") {
            processed = processed.replace("||", ";");
        }
        if processed.contains("if ") && processed.contains("elif") {
            return self.exec_if_bug(&processed);
        }
        self.exec_via_bash(&processed)
    }
    fn is_panic_break(&self, s: &str) -> bool {
        let t = s.trim();
        if t == "break" || t.starts_with("break;") || t.starts_with("break ") {
            if s.contains("for ") || s.contains("while ") { return false; }
            return true;
        }
        if t.contains(";") {
            let parts: Vec<&str> = t.split(';').collect();
            for p in parts {
                let ptrim = p.trim();
                if ptrim == "break" || ptrim.starts_with("break ") {
                    if !(s.contains("for ") || s.contains("while ")) { return true; }
                }
            }
        }
        false
    }
    fn is_panic_continue(&self, s: &str) -> bool {
        let t = s.trim();
        if t == "continue" || t.starts_with("continue;") || t.starts_with("continue ") {
            if s.contains("for ") || s.contains("while ") { return false; }
            return true;
        }
        if t.contains(";") {
            let parts: Vec<&str> = t.split(';').collect();
            for p in parts {
                let ptrim = p.trim();
                if ptrim == "continue" {
                    if !(s.contains("for ") || s.contains("while ")) { return true; }
                }
            }
        }
        false
    }
    fn is_panic_return(&self, s: &str) -> bool {
        let t = s.trim();
        if t == "return" || t.starts_with("return ") || t.starts_with("return;") {
            if s.contains("()") { return false; }
            return true;
        }
        if t.contains(";") {
            let parts: Vec<&str> = t.split(';').collect();
            for p in parts {
                let ptrim = p.trim();
                if ptrim == "return" || ptrim.starts_with("return ") {
                    if !s.contains("()") { return true; }
                }
            }
        }
        false
    }
