                if login_count > 0 { usage_flags.push("--login"); }
                usage_flags.push("--norc");
                let usage = format!("{} {}", exe_name, usage_flags.join(" "));
                eprintln!("error: The argument '--norc' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\nFor more information try --help", usage);
                exit(1);
            }
            i += 1;
            continue;
        }
        if a == "-c" {
            c_count += 1;
            if c_count > 1 {
                eprintln!("error: The argument '-c <command>' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} -c <command>\n\nFor more information try --help", exe_name);
                exit(1);
            }
            seen_c = true;
            c_value_index = i;
            if i+1 >= args.len() {
                // Missing value
                let mut usage = format!("{} -c <command>", exe_name);
                if login_count > 0 { usage.push_str(" --login"); }
                if norc_count > 0 { usage.push_str(" --norc"); }
                // Original USAGE for -c missing includes flags present after -c? For -c --norc missing, usage includes --norc, for -c --login missing includes --login
                // But our current parsing hasn't yet seen flags after -c because we are at -c and next is missing. However flags after -c that are present (like --norc after -c) would be considered value if they were present, but missing means next arg doesn't exist, so no after flags.
                // For case "-c --norc" where --norc is next arg, we treat as value? But earlier we saw -c --norc gives missing value error with USAGE ... --norc, meaning --norc is NOT consumed as value, it's considered as separate flag and -c missing value error includes --norc in usage.
                // So if next arg exists but is a known flag other than help, should we treat as missing value or as value?
                // For -c, the next arg is expected to be command string, which could be any string, even starting with -. But clap treats --norc as flag, not value, causing missing value error.
                // So -c's value is required and cannot be a flag (except help?). For --norc, it's considered flag, not value, so error.
                // So if i+1 >= len, missing value with current flags
                eprintln!("error: The argument '-c <command>' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help", usage);
                exit(1);
            } else {
                let next = &args[i+1];
                // Check if next is a flag that should cause missing value error
                // For -c, if next is --norc, --login, -l, --version? But --version would have been handled earlier? Actually --version before -c missing would be version, not missing.
                // So if next is known flag other than help, treat as missing value error
                // If next is --help or -h, treat as help (already handled) but we already handled help earlier, so not here.
                // So for -c, if next is "--norc" or "--login" or "-l", it's missing value error
                // Also if next is "-c", it's missing value plus duplicate? But -c requires value, duplicate would be after?
                // For simplicity, if next starts with '-' and is known flag (except help), then missing value error
                if next == "--norc" || next == "--login" || next == "-l" {
                    let mut usage = format!("{} -c <command>", exe_name);
                    // Include that flag in usage
                    if next == "--norc" { usage.push_str(" --norc"); }
                    if next == "--login" || next == "-l" { usage.push_str(" --login"); }
                    // Also include other flags present
                    if login_count > 0 && next != "--login" && next != "-l" { usage.push_str(" --login"); }
                    if norc_count > 0 && next != "--norc" { usage.push_str(" --norc"); }
                    eprintln!("error: The argument '-c <command>' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help", usage);
                    exit(1);
                }
                // Otherwise, consume next as value
                c_value = Some(next.clone());
                i += 2;
                continue;
            }
        }
        if a.starts_with('-') {
            // Unknown flag
            // Need to determine USAGE based on current flags
            let mut usage = format!("{} [FLAGS] [OPTIONS] [FILE]", exe_name);
            // But for specific contexts, USAGE varies:
            // If -c is present (seen), USAGE is "executable -c <command>" or "executable -c <command> --norc" etc
            // If only login/norc present without -c, USAGE is "executable --login" or "executable --norc" etc
            // For general unknown, USAGE is generic [FLAGS] [OPTIONS] [FILE] unless -c present?
            // Let's check examples:
            // --unknown => USAGE executable [FLAGS] [OPTIONS] [FILE]
            // --norc --unknown => USAGE executable --norc
            // -l --unknown => USAGE executable --login
            // -c echo hi --unknown => USAGE executable -c <command>
            // --norc -c echo hi --unknown => USAGE executable -c <command> --norc
            // -l -c echo hi --unknown => USAGE executable -c <command> --login
            // So we need to generate USAGE based on flags present before unknown
            let has_c = c_value.is_some() || seen_c;
            let mut usage_str = String::new();
            if has_c {
                usage_str = format!("{} -c <command>", exe_name);
                if login_count > 0 { usage_str.push_str(" --login"); }
                if norc_count > 0 { usage_str.push_str(" --norc"); }
            } else if login_count > 0 || norc_count > 0 {
                usage_str = format!("{} {}", exe_name, if login_count>0 {"--login"} else {""});
                if norc_count>0 {
                    if login_count>0 { usage_str.push_str(" --norc"); } else { usage_str = format!("{} --norc", exe_name); }
                }
                if usage_str == exe_name { usage_str = format!("{} [FLAGS] [OPTIONS] [FILE]", exe_name); }
            } else {
                usage_str = format!("{} [FLAGS] [OPTIONS] [FILE]", exe_name);
            }
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help", a, usage_str);
            exit(1);
        } else {
            // Positional arg (FILE)
            if c_value.is_some() {
                // If -c is present, file is extra? Original: -c echo hi extra => success (extra ignored?) Wait we saw -c echo hi extra => hi (0) ignoring extra, but -c echo hi extra extra2 => error extra2. So one extra after -c is allowed (maybe ignored), but second extra causes error.
                // Let's check: -c echo hi extra => code 0, output hi. So one extra positional after -c is allowed (maybe treated as extra arg for command? But our shell ignores extra args).
                // -c echo hi extra extra2 => error extra2 with USAGE executable -c <command>
                // So for -c case, first extra positional is allowed, second extra is error.
                // Need to handle.
                if file_value.is_some() {
                    // Already have one extra, now second extra => error
                    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} -c <command>\n\nFor more information try --help", a, exe_name);
                    exit(1);
                } else {
                    // First extra after -c is allowed, treat as file_value but ignore? We'll store but not error
                    file_value = Some(a.clone());
                    // But should we allow? Original allows one extra without error, so we set and continue
                    i += 1;
                    continue;
                }
            } else {
                if file_value.is_some() {
                    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} [FLAGS] [OPTIONS] [FILE]\n\nFor more information try --help", a, exe_name);
                    exit(1);
                } else {
                    file_value = Some(a.clone());
                }
            }
            i += 1;
            continue;
        }
    }

    // After parsing, decide execution
    // Check for duplicate handling already done
    // Now execute
    let is_login = login_count > 0;
    let norc = norc_count > 0;
    let cmd_opt = c_value;
    let file_opt = file_value;

    // Note: if -c present, file_opt may be Some (first extra) but original allows it and still executes -c, ignoring file? We saw -c echo hi extra => executes hi, ignores extra. So we should prioritize -c over file.

    if let Some(cmd_str) = cmd_opt {
        let mut shell = Shell::new(is_login);
        if !norc {
            shell.load_nshrc();
        }
        let code = shell.exec_string(&cmd_str);
        exit(code);
    } else if let Some(file) = file_opt {
        // Check if file exists? If file is extra after -c, we already handled as -c case, so this file is true file execution
        // Need to handle -- terminator case: -- --help should be file execution with file "--help"
        // Already handled after_double_dash
        let content = match fs::read_to_string(&file) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("nsh: panicked at src/main.rs:114:34:");
                eprintln!("failed to open the file: Os {{ code: 2, kind: NotFound, message: \"{}\" }}", e);
                eprintln!("nsh:    0:     0x559699ac14fc - <unknown>");
                eprintln!("   1:     0x559699a18594 - <unknown>");
                eprintln!("   2:     0x559699b507f6 - <unknown>");
                eprintln!("   3:     0x559699b79738 - <unknown>");
                eprintln!("   4:     0x559699b79699 - <unknown>");
                eprintln!("   5:     0x559699b7968c - <unknown>");
                eprintln!("   6:     0x559699b167df - <unknown>");
                eprintln!("   7:     0x559699a17534 - <unknown>");
                eprintln!("   8:     0x559699a562d3 - <unknown>");
                eprintln!("   9:     0x559699ab7323 - <unknown>");
                eprintln!("  10:     0x7fe485e55d90 - <unknown>");
                eprintln!("  11:     0x7fe485e55e40 - __libc_start_main");
                eprintln!("  12:     0x5596999fc4b5 - <unknown>");
                eprintln!("  13:                0x0 - <unknown>");
                eprintln!();
                eprintln!("nsh: Something went wrong. Check out ~/.nsh.log and please file this bug on GitHub: https://github.com/nuta/nsh/issues");
                log_error(&format!("panicked at src/main.rs:114:34: failed to open file {}", e));
                exit(101);
            }
        };
        let mut shell = Shell::new(is_login);
        if !norc {
            shell.load_nshrc();
        }
        let code = shell.exec_string(&content);
        exit(code);
    } else {
        let is_tty = unsafe { libc::isatty(libc::STDOUT_FILENO) == 1 };
        if !is_tty {
            eprintln!("nsh: warning: stdout is not a tty");
            exit(0);
        }
        let mut shell = Shell::new(is_login);
        if !norc {
            shell.load_nshrc();
        }
        shell.interactive_loop();
    }
}

