                    if i+1 < args.len() && (args[i+1] == "--help" || args[i+1] == "-h") {
                        i += 2;
                        continue;
                    } else {
                        // missing value error would be triggered, but help takes precedence? We saw -h -c => help (help before -c missing). So help before -c missing gives help.
                        // If help is after -c missing, then -c missing is before help, should we still give help or missing error?
                        // Example -c --norc: there's no help, so missing error.
                        // Example -c and then help later: -c --help => help (as above)
                        // So for unknown detection, we should not treat missing value as unknown; it's a different error.
                        // For help case, we ignore missing value.
                        i += 1;
                        continue;
                    }
                } else {
                    let next = &args[i+1];
                    if next == "--help" || next == "-h" {
                        // help is value? But help takes precedence, so we would have already returned help, not treat as error.
                        i += 2;
                        continue;
                    } else {
                        // next is value for -c, skip it
                        i += 2;
                        continue;
                    }
                }
            }
            if a.starts_with('-') {
                if !is_known_flag(a) {
