    }

    if let Some(v_pos) = version_pos {
        let mut i = 1;
        while i < v_pos {
            let a = &args[i];
            if a == "-c" {
                if i+1 >= args.len() {
                    i += 1;
                    continue;
                } else {
                    let next = &args[i+1];
                    if next == "--version" {
                        i += 2;
                        continue;
                    } else {
                        i += 2;
                        continue;
                    }
                }
            }
            if a.starts_with('-') {
                if !is_known_flag(a) {
                    if a == "--" { break; }
                    // Determine usage for version error: if there are other flags before unknown, usage shows those flags?
                    // Original for --version --unknown => USAGE executable --version (includes --version)
                    // For --unknown --version => USAGE executable [FLAGS]... (not --version)
                    // So unknown before version uses generic usage, not specific version usage?
                    // Let's mimic: if unknown before version, usage is generic [FLAGS] unless version was earlier?
                    // For version case, we need to produce correct USAGE line
                    // For --version --unknown: error is "Found argument '--unknown'... USAGE: executable --version"
                    // For --unknown --version: USAGE is generic
                    // So for version error, if version appears before unknown, usage includes --version
                    // But our current check is unknown before version, so version after unknown, so usage is generic.
                    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} [FLAGS] [OPTIONS] [FILE]\n\nFor more information try --help", a, exe_name);
                    exit(1);
                }
            }
            i += 1;
        }
        // Check unknown before version specifically for --version case where version before unknown?
        // That case is when version pos < unknown pos. But we are only checking unknown before version, so version before unknown not checked here.
        // However we also need to detect unknown after version and error with USAGE --version
        // That will be handled later in general parsing, but for version printing, we should check if there's any unknown after version that would cause error with USAGE --version
        // Actually original: --version extra => prints version (0), not error. So extra positional after version is ignored, not error.
        // And --version --unknown => error with USAGE --version. So --unknown after version is error, not ignored.
        // So extra plain arg after version is ignored, but flag after version is error.
        // For simplicity, if version_pos is Some and there is no unknown before it, we should print version and exit 0, ignoring extra positional after
        // But need to detect flag after version that's unknown => error?
        // Let's scan args after version_pos for unknown flag
        for a in args.iter().skip(v_pos+1) {
            if a.starts_with('-') && a != "--" {
                if !is_known_flag(a) && a != "--help" && a != "-h" {
                    // But help already handled, version already
                    // For --version --unknown, this would trigger
                    // Need to print error with USAGE --version
                    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} --version\n\nFor more information try --help", a, exe_name);
                    exit(1);
                }
                // Known flags after version: --help would have already been handled, but if version before help, help after version? We saw --version --help => help, not version. So help after version still triggers help? But we already returned help if help_pos exists before version? Actually help_pos would be after version_pos, but we already checked help before version and returned help, so version before help gives help.
                // So for version case, if there's help after version, we would have returned help already, not version.
            }
        }
