        println!("0.4.2");
        exit(0);
    }

    // Now general parsing for remaining args (no help/version to handle)
    // We need to handle duplicate flags, missing values, unknown flags, extra positional
    // Implement manual parsing state

    let mut login_count = 0;
    let mut norc_count = 0;
    let mut c_count = 0;
    let mut c_value: Option<String> = None;
    let mut file_value: Option<String> = None;
    let mut pos = 1;
    let mut after_double_dash = false;
    let mut seen_c = false;
    let mut c_value_index = 0;

    // First, detect duplicates and missing values etc, but also need to produce correct USAGE strings
    // USAGE strings vary depending on which flags are present
    // For errors like duplicate --norc, USAGE is "executable -c <command> --norc" or "executable -c <command> --login --norc" etc depending on flags present
    // For missing -c value, USAGE is "executable -c <command> ..." with flags that were present? Let's collect.

    // We'll parse sequentially
    let mut i = 1;
    while i < args.len() {
