            continue;
        }
        if a == "--" {
            // "--" is terminator: next arg is treated as file? But original behavior for "-- --help" etc: -- --help => panic file not found (treats --help as file)
            // And "-- -c echo hi" => error Found argument 'echo hi' with USAGE [FLAGS]...
            // So after --, the next token is not flag, it's file, even if it looks like flag.
            // We'll set flag and continue
            after_double_dash = true;
            i += 1;
            continue;
        }
        if a == "-h" || a == "--help" {
            // Already handled, but if we reach here means help not earlier? Actually we already exited if help found, so this shouldn't happen unless help after other error? But we already handled help before version, so if we are here, no help.
