    fn exec_if_bug(&mut self, s: &str) -> i32 {
        let mut conds: Vec<String> = Vec::new();
        let mut bodies: Vec<String> = Vec::new();
        let mut has_else = false;
        let mut else_body = String::new();
        let parts: Vec<&str> = s.split("elif").collect();
        let first = parts[0];
        let re_first = regex::Regex::new(r"if\s+([^;]+);\s*then\s+(.+)").unwrap();
        if let Some(cap) = re_first.captures(first) {
            let cond = cap[1].trim().to_string();
            let mut body = cap[2].trim().to_string();
            if body.contains("else") {
                let idx = body.find("else").unwrap();
                let else_part = body[idx..].to_string();
                body = body[..idx].trim().trim_end_matches(';').trim().to_string();
                let re_else = regex::Regex::new(r"else\s+([^;]+)").unwrap();
                if let Some(cap2) = re_else.captures(&else_part) {
                    has_else = true;
                    else_body = cap2[1].trim().to_string();
                }
            } else if body.contains("fi") {
                let idx = body.find("fi").unwrap();
                body = body[..idx].trim().trim_end_matches(';').trim().to_string();
            } else {
                body = body.trim_end_matches(';').trim().to_string();
            }
            conds.push(cond);
            bodies.push(body);
        }
        for part in parts.iter().skip(1) {
            let re_elif = regex::Regex::new(r"\s*([^;]+);\s*then\s+(.+)").unwrap();
            if let Some(cap) = re_elif.captures(part) {
                let cond = cap[1].trim().to_string();
                let mut body = cap[2].trim().to_string();
                if body.contains("else") {
                    let idx = body.find("else").unwrap();
                    let else_part = body[idx..].to_string();
                    body = body[..idx].trim().trim_end_matches(';').trim().to_string();
                    let re_else = regex::Regex::new(r"else\s+([^;]+)").unwrap();
                    if let Some(cap2) = re_else.captures(&else_part) {
                        has_else = true;
                        else_body = cap2[1].trim().to_string();
                    }
                } else if body.contains("fi") {
                    let idx = body.find("fi").unwrap();
                    body = body[..idx].trim().trim_end_matches(';').trim().to_string();
                } else {
                    body = body.trim_end_matches(';').trim().to_string();
                }
                conds.push(cond);
                bodies.push(body);
            }
        }
        let mut cond_results: Vec<bool> = Vec::new();
        for cond in &conds {
            let code = self.eval_condition(cond);
            cond_results.push(code == 0);
        }
        let output;
        if cond_results.is_empty() { return 0; }
        if cond_results[0] {
            output = bodies[0].clone();
        } else {
            let any_true = cond_results.iter().skip(1).any(|&v| v);
            if any_true {
                output = bodies[0].clone();
            } else {
                if has_else {
                    output = else_body.clone();
                } else {
                    return 0;
                }
            }
        }
        if output.is_empty() { return 0; }
        return self.exec_via_bash(&output);
    }
    fn eval_condition(&mut self, cond: &str) -> i32 {
        let mut cmd = std::process::Command::new("bash");
        cmd.arg("-c").arg(cond);
        for (k,v) in &self.env { cmd.env(k,v); }
        let out = cmd.output().unwrap();
        out.status.code().unwrap_or(1)
    }
    fn check_parse_errors(&self, s: &str) -> Option<(String, i32)> {
        if regex::Regex::new(r"[A-Za-z_][A-Za-z0-9_]*=\s*;").unwrap().is_match(s) {
            let line = s.lines().next().unwrap_or(s);
            let err = format!("nsh: parse error:  --> 1:5\n  |\n1 | {}\n  |     ^---\n  |\n  = expected literal_span, tilde_span, any_string_span, any_char_span, command_span, proc_subst_direction, backtick_span, expr_span, param_ex_span, param_span, double_quoted_span, single_quoted_span, or initializer", line);
            return Some((err, 255));
        }
        if s.contains("<< \"") || s.contains("<< '") {
            for (idx, line) in s.lines().enumerate() {
                if line.contains("<<") {
                    if let Some(pos) = line.find("<<") {
                        let after = line[pos+2..].trim_start();
                        if after.starts_with('"') || after.starts_with('\'') {
                            let col = pos + 3 + 1;
                            let err = format!("nsh: parse error:  --> {}:{}\n  |\n{} | {}\n  | {}^---\n  |\n  = expected heredoc_marker", idx+1, col, idx+1, line, " ".repeat(pos+2));
                            return Some((err, 255));
                        }
                    }
                }
            }
        }
        let re = regex::Regex::new(r"\$\{([^}]+)\}").unwrap();
        for cap in re.captures_iter(s) {
            let inside = &cap[1];
            if inside.starts_with('#') {
                let var = &inside[1..];
                if var.is_empty() {
                    let line = s.lines().next().unwrap_or(s);
                    let err = format!("nsh: parse error:  --> 1:9\n  |\n1 | {}\n  |         ^---\n  |\n  = expected var_name", line);
                    return Some((err, 255));
                }
                if regex::Regex::new(r"^[A-Za-z_][A-Za-z0-9_]*$").unwrap().is_match(var) { continue; } else { continue; }
            }
            let var_re = regex::Regex::new(r"^([A-Za-z_][A-Za-z0-9_]*)").unwrap();
            if let Some(m) = var_re.find(inside) {
                let var_end = m.end();
                let rest = &inside[var_end..];
                if rest.is_empty() { continue; }
                if rest.starts_with(":-") || (rest.starts_with("-") && !rest.starts_with("--")) { continue; }
                else if rest.starts_with(":=") { continue; }
                else if rest.starts_with("=") { continue; }
                else {
                    let full_match = cap.get(0).unwrap();
                    let start = full_match.start();
                    let op_pos = start + 2 + var_end;
                    let line = s.lines().next().unwrap_or(s);
                    let col = op_pos + 1;
                    let err = format!("nsh: parse error:  --> 1:{}\n  |\n1 | {}\n  | {}^---\n  |\n  = expected param_op", col, line, " ".repeat(op_pos));
                    return Some((err, 255));
                }
            }
        }
        None
    }
    fn exec_via_bash(&mut self, s: &str) -> i32 {
        let mut expanded = s.to_string();
        if let Some(home) = self.env.get("HOME").cloned() {
            if expanded.contains("~") {
                if regex::Regex::new(r"~[A-Za-z0-9_]+").unwrap().is_match(&expanded) {
                    eprintln!("nsh: warning: ~user is not yet supported");
                }
                expanded = expanded.replace("~/", &format!("{}/", home));
                if expanded == "~" {
                    expanded = home.clone();
                } else {
                    expanded = expanded.replace(" ~ ", &format!(" {} ", home));
                    if expanded.contains("echo ~") {
                        expanded = expanded.replace("echo ~", &format!("echo {}", home));
                    }
                    expanded = expanded.replace(" ~;", &format!(" {};", home));
                    if expanded.starts_with("~ ") {
                        expanded = format!("{} {}", home, &expanded[2..]);
                    }
                    if expanded.starts_with("~;") {
                        expanded = format!("{};", home);
                    }
                }
                if expanded.starts_with("~/") {
                    expanded = format!("{}/{}", home, &expanded[2..]);
                }
            }
        }
        let words: Vec<&str> = expanded.split_whitespace().collect();
        for w in words {
            if w.contains('*') || w.contains('?') {
                if (w.starts_with('"') && w.ends_with('"')) || (w.starts_with('\'') && w.ends_with('\'')) { continue; }
                match glob::glob(w) {
                    Ok(mut paths) => {
                        if paths.next().is_none() {
                            eprintln!("nsh: error: no matches");
                            self.last_status = 1;
                            return 1;
                        }
                    },
                    Err(_) => { self.panic_glob(); return 101; }
                }
            }
        }
        let mut to_run = expanded.clone();
        let first_word = to_run.split_whitespace().next().unwrap_or("").trim_matches(|c| c=='"' || c=='\'');
        if let Some(alias_val) = self.aliases.get(first_word).cloned() {
            to_run = to_run.replacen(first_word, &alias_val, 1);
        }
        if to_run.contains("while ") {
            if to_run.contains("break") && (to_run.contains("while true") || to_run.contains("while [") || to_run.contains("while test")) {
                if to_run.contains("while true") || to_run.contains("while /bin/true") {
                    let re_body = regex::Regex::new(r"while\s+[^;]+;\s*do\s+(.*)\s*;\s*done").unwrap();
                    if let Some(cap) = re_body.captures(&to_run) {
                        let body = cap[1].to_string();
                        if body.contains("echo") {
                            loop {
                                let mut cmd = std::process::Command::new("bash");
                                cmd.arg("-c").arg(&body);
                                for (k,v) in &self.env { cmd.env(k,v); }
                                let out = cmd.output().unwrap();
                                io::stdout().write_all(&out.stdout).unwrap();
                                io::stderr().write_all(&out.stderr).unwrap();
                            }
                        } else {
                            loop {
                                std::thread::sleep(std::time::Duration::from_millis(10));
                            }
                        }
                    } else {
                        loop { std::thread::sleep(std::time::Duration::from_millis(10)); }
                    }
                }
                if to_run.contains("while [") && to_run.contains("break") {
                    if to_run.contains("[ $i -lt") {
                        self.panic_unexpected("Break");
                        return 101;
                    }
                    if to_run.contains("[ 1 -eq 1 ]") {
                        loop { std::thread::sleep(std::time::Duration::from_millis(10)); }
                    }
                }
            }
            if to_run.contains("while true") && to_run.contains("continue") {
                loop {
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
            }
        }
        if to_run.trim_start().starts_with("cd ") || to_run.trim() == "cd" { return self.builtin_cd(&to_run); }
        if to_run.trim_start().starts_with("export") { return self.builtin_export(&to_run); }
        if to_run.trim_start().starts_with("unset ") { return self.builtin_unset(&to_run); }
        if to_run.trim_start().starts_with("alias") { return self.builtin_alias(&to_run); }
        if to_run.trim_start().starts_with("source ") { return self.builtin_source(&to_run); }
        if to_run.trim_start().starts_with("set ") || to_run.trim() == "set" { return self.builtin_set(&to_run); }
        if to_run.trim_start().starts_with("jobs") { return self.builtin_jobs(&to_run); }
        if to_run.trim_start().starts_with("wait") { return self.builtin_wait(&to_run); }
        if to_run.trim_start().starts_with("exit") { return self.builtin_exit(&to_run); }
        if to_run.trim_start().starts_with("exec ") { return self.builtin_exec(&to_run); }
        if to_run.trim_start().starts_with("eval ") { return self.builtin_eval(&to_run); }
        if to_run.trim_start().starts_with("shift") { return self.builtin_shift(&to_run); }
        if to_run.trim_start().starts_with("pwd") { return self.builtin_pwd(&to_run); }
        if to_run.trim().starts_with("kill") { return self.builtin_kill(&to_run); }
        if to_run.trim().starts_with("fg") || to_run.trim().starts_with("bg") { return self.builtin_fg_bg(&to_run); }

        let mut bg = false;
        let mut cmd_str = to_run.clone();
        if cmd_str.trim_end().ends_with('&') {
            bg = true;
            cmd_str = cmd_str.trim_end().trim_end_matches('&').trim().to_string();
        }

        let bash_cmd = format!("shopt -s dotglob 2>/dev/null; shopt -s nullglob 2>/dev/null; {}", cmd_str);
        let mut cmd = std::process::Command::new("bash");
        cmd.arg("-c").arg(&bash_cmd);
        for (k,v) in &self.env { cmd.env(k, v); }
        let output = cmd.output();
        match output {
            Ok(out) => {
                io::stdout().write_all(&out.stdout).unwrap();
                io::stderr().write_all(&out.stderr).unwrap();
                let code = out.status.code().unwrap_or(1);
                self.last_status = code;
                self.update_env_from_string(&to_run, code);
                if bg {
                    println!("[1] Done: {}", cmd_str);
                }
                code
            },
            Err(e) => { eprintln!("nsh: failed to exec: {}", e); 1 }
        }
    }
    fn builtin_cd(&mut self, s: &str) -> i32 {
        let args: Vec<&str> = s.split_whitespace().collect();
        let target = if args.len() == 1 {
            match self.env.get("HOME") { Some(h) => h.clone(), None => "/".to_string() }
        } else if args[1] == "-" {
            match env::var("OLDPWD").or_else(|_| self.env.get("OLDPWD").cloned().ok_or(env::VarError::NotPresent)) {
                Ok(old) => old,
                Err(_) => "/".to_string(),
            }
        } else { args[1].to_string() };
        let old_pwd = env::current_dir().unwrap_or_else(|_| Path::new("/").to_path_buf());
        match env::set_current_dir(&target) {
            Ok(_) => {
                let new_pwd = env::current_dir().unwrap();
                self.env.insert("OLDPWD".to_string(), old_pwd.to_string_lossy().to_string());
                self.env.insert("PWD".to_string(), new_pwd.to_string_lossy().to_string());
                env::set_var("OLDPWD", old_pwd.to_string_lossy().to_string());
                env::set_var("PWD", new_pwd.to_string_lossy().to_string());
                0
            },
            Err(e) => { eprintln!("nsh: cd: No such file or directory (os error {}): `{}`", e.raw_os_error().unwrap_or(2), target); 1 }
        }
    }
    fn builtin_export(&mut self, s: &str) -> i32 {
        let trimmed = s.trim();
        if trimmed == "export" { return 0; }
        let rest = trimmed.trim_start_matches("export").trim();
        if rest.is_empty() { return 0; }
        let parts: Vec<&str> = rest.split_whitespace().collect();
        for part in parts {
            if part.contains('=') {
                let mut kv = part.splitn(2, '=');
                let k = kv.next().unwrap().to_string();
                let mut v = kv.next().unwrap().to_string();
                if (v.starts_with('"') && v.ends_with('"')) || (v.starts_with('\'') && v.ends_with('\'')) { v = v[1..v.len()-1].to_string(); }
                self.env.insert(k.clone(), v.clone());
                env::set_var(&k, &v);
            }
        }
        0
    }
    fn builtin_unset(&mut self, s: &str) -> i32 {
        let args: Vec<&str> = s.split_whitespace().collect();
        if args.len() < 2 { return 0; }
        for arg in args.iter().skip(1) {
            if arg.starts_with('-') {
                eprintln!("nsh: unset: error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    unset <NAME>\n\nFor more information try --help\n", arg);
                return 1;
            }
            self.env.remove(*arg);
            env::remove_var(*arg);
        }
        0
    }
    fn builtin_alias(&mut self, s: &str) -> i32 {
        let trimmed = s.trim();
        if trimmed == "alias" {
            for (k,v) in &self.aliases { println!("{}='{}'", k, v); }
            return 0;
        }
        let rest = trimmed.trim_start_matches("alias").trim();
        if !rest.contains('=') {
            eprintln!("nsh: alias:  --> 1:1\n  |\n1 | {}\n  | ^---\n  |\n  = expected alias", rest);
            return 1;
        }
        let eq = rest.find('=').unwrap();
        let name = rest[..eq].trim().to_string();
        let mut value = rest[eq+1..].trim().to_string();
        if (value.starts_with('"') && value.ends_with('"')) || (value.starts_with('\'') && value.ends_with('\'')) { value = value[1..value.len()-1].to_string(); }
        self.aliases.insert(name, value);
        0
    }
    fn builtin_source(&mut self, s: &str) -> i32 {
        let args: Vec<&str> = s.split_whitespace().collect();
        if args.len() < 2 {
            eprintln!("nsh: failed open the file: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}");
            return 1;
        }
        let path = args[1];
        match fs::read_to_string(path) {
            Ok(content) => self.exec_string(&content),
            Err(e) => { eprintln!("nsh: failed open the file: Os {{ code: 2, kind: NotFound, message: \"{}\" }}", e); 1 }
        }
    }
    fn builtin_set(&mut self, s: &str) -> i32 {
        let args: Vec<&str> = s.split_whitespace().collect();
        if args.len() == 1 { return 0; }
        for arg in args.iter().skip(1) {
            match *arg {
                "-e" => self.options_e = true,
                "-u" => self.options_u = true,
                "-n" => self.options_n = true,
                "-h" | "--help" => { println!("nsh: set: set 0.4.2\nSet command.\n\nUSAGE:\n    set [FLAGS]\n\nFLAGS:\n    -e               \n    -h, --help       Prints help information\n    -n               \n    -u               \n    -V, --version    Prints version information\n"); return 0; },
                "--version" | "-V" => { println!("0.4.2"); return 0; },
                _ => {
                    eprintln!("nsh: set: error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    set [FLAGS]\n\nFor more information try --help\n", arg);
                    return 1;
                }
            }
        }
        0
    }
    fn builtin_jobs(&mut self, _s: &str) -> i32 { 0 }
    fn builtin_wait(&mut self, s: &str) -> i32 {
        let args: Vec<&str> = s.split_whitespace().collect();
        if args.len() > 1 {
            let id = args[1];
            if let Ok(_num) = id.parse::<u32>() {
                eprintln!("nsh: invalid job id `{}'", id);
                return 1;
            } else {
                eprintln!("nsh: invalid job id `{}'", id);
                return 1;
            }
        }
        0
    }
    fn builtin_exit(&mut self, s: &str) -> i32 {
        let args: Vec<&str> = s.split_whitespace().collect();
        if args.len() > 1 {
            if let Ok(code) = args[1].parse::<i32>() { exit(code); } else { exit(0); }
        } else { exit(0); }
    }
    fn builtin_exec(&mut self, s: &str) -> i32 {
        let rest = s.trim_start_matches("exec").trim();
        if rest.is_empty() { return 0; }
        self.exec_via_bash(rest)
    }
    fn builtin_eval(&mut self, s: &str) -> i32 {
        let rest = s.trim_start_matches("eval").trim();
        let mut cmd = rest.to_string();
        if (cmd.starts_with('"') && cmd.ends_with('"')) || (cmd.starts_with('\'') && cmd.ends_with('\'')) { cmd = cmd[1..cmd.len()-1].to_string(); }
        self.exec_string(&cmd)
    }
    fn builtin_shift(&mut self, _s: &str) -> i32 { 0 }
    fn builtin_pwd(&mut self, s: &str) -> i32 {
        if s.contains("--help") {
            let mut cmd = std::process::Command::new("bash");
            cmd.arg("-c").arg(s);
            for (k,v) in &self.env { cmd.env(k,v); }
            let out = cmd.output().unwrap();
            io::stdout().write_all(&out.stdout).unwrap();
            io::stderr().write_all(&out.stderr).unwrap();
            return out.status.code().unwrap_or(0);
        }
        match env::current_dir() {
            Ok(p) => { println!("{}", p.display()); 0 },
            Err(_) => 1,
        }
    }
    fn builtin_kill(&mut self, s: &str) -> i32 {
        let mut cmd = std::process::Command::new("bash");
        cmd.arg("-c").arg(s);
        for (k,v) in &self.env { cmd.env(k,v); }
        let out = cmd.output().unwrap();
        io::stdout().write_all(&out.stdout).unwrap();
        io::stderr().write_all(&out.stderr).unwrap();
        out.status.code().unwrap_or(1)
    }
    fn builtin_fg_bg(&mut self, s: &str) -> i32 {
        eprintln!("nsh: no jobs to run");
        1
    }
    fn update_env_from_string(&mut self, s: &str, _code: i32) {
        let export_re = regex::Regex::new(r"export\s+([A-Za-z_][A-Za-z0-9_]*)(?:=([^\s;]+))?").unwrap();
        for cap in export_re.captures_iter(s) {
            let k = cap[1].to_string();
            if let Some(v_match) = cap.get(2) {
                let mut v = v_match.as_str().to_string();
                if (v.starts_with('"') && v.ends_with('"')) || (v.starts_with('\'') && v.ends_with('\'')) { v = v[1..v.len()-1].to_string(); }
                self.env.insert(k.clone(), v.clone());
                env::set_var(&k, &v);
            }
        }
        let alias_re = regex::Regex::new(r#"alias\s+([A-Za-z_][A-Za-z0-9_]*)=["']?([^"'\n;]+)["']?"#).unwrap();
